// Original source pixels are sampled through measured isolation spans, never repainted.
const paths=new WeakMap();
export function sourceClipPath(frame){if(!frame.sourceClipSpans?.length||typeof Path2D==='undefined')return null;let path=paths.get(frame);if(!path){path=new Path2D();for(const [x,width,y,height]of frame.sourceClipSpans)path.rect(x,y,width,height);paths.set(frame,path);}return path;}
export function drawOriginalRegion(c,image,frame,source,dx,dy,width,height){if(!(source[2]>0&&source[3]>0&&width>0&&height>0))return;const path=sourceClipPath(frame);if(!path){c.drawImage(image,...source,dx,dy,width,height);return;}c.save();c.translate(dx,dy);c.scale(width/source[2],height/source[3]);c.translate(-source[0],-source[1]);c.clip(path);c.drawImage(image,...source,...source);c.restore();}
export function sourceMask(frame){if(!frame.sourceClipSpans?.length)return '';const [x,y,w,h]=frame.sourceRect||frame.rect,rects=frame.sourceClipSpans.map(([sx,sw,sy,sh])=>`<rect x="${sx-x}" y="${sy-y}" width="${sw}" height="${sh}" fill="white"/>`).join('');return `url("data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${rects}</svg>`)}")`;}
